('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datenmanipulation ist ein Schadensszenario im IT-Grundschutz. b) Schadensszenarien haben keine rechtlichen Folgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Manipulation ja, Folgen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Phishing kann ein Schadensszenario im IT-Grundschutz sein. b) Schadensszenarien betreffen nur technische Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phishing ja, auch organisatorisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Naturkatastrophen sind Schadensszenarien im IT-Grundschutz. b) Schadensszenarien verursachen keinen Rufschaden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Katastrophen ja, Rufschaden möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

